import type { FreeCamera, SceneContext } from "@babylonjs/lite";
import { attachFreeControl, createFreeCamera } from "@babylonjs/lite";

type Vec = { x: number; y: number; z: number };

export interface Walkthrough {
  readonly camera: FreeCamera;
  jumpTo(eye: Vec, target: Vec): void;
  dispose(): void;
}

// attachFreeControl aims from FreeCamera._yaw/_pitch, which it only sets at
// creation and from its own drags; a hand-set target is replaced on the next
// key move or drag. So a jump must resync _yaw/_pitch, or W and drags would
// keep aiming from the previous viewpoint.
const PITCH_LIMIT = Math.PI / 2 - 0.01;

export function createWalkthrough(
  canvas: HTMLCanvasElement,
  scene: SceneContext,
  eye: Vec,
  target: Vec
): Walkthrough {
  const camera = createFreeCamera(eye, target);
  scene.camera = camera;

  // The scene is required: without it the control's per-frame step never moves the camera.
  const detach = attachFreeControl(camera, canvas, scene);

  let disposed = false;

  return {
    camera,

    jumpTo(eye, target) {
      // Move both ends of the view; moving position alone would turn the camera.
      camera.position.x = eye.x;
      camera.position.y = eye.y;
      camera.position.z = eye.z;
      camera.target.x = target.x;
      camera.target.y = target.y;
      camera.target.z = target.z;

      const dx = target.x - eye.x;
      const dy = target.y - eye.y;
      const dz = target.z - eye.z;
      camera._yaw = Math.atan2(dx, dz);
      const pitch = Math.atan2(dy, Math.hypot(dx, dz));
      camera._pitch = Math.min(PITCH_LIMIT, Math.max(-PITCH_LIMIT, pitch));
    },

    dispose() {
      if (disposed) return;
      disposed = true;
      detach();
    },
  };
}
```

I added `src/walkthrough.ts`, which creates a free camera at the given eye/target, sets it as `scene.camera`, and attaches the standard free control with the scene (so its `_beforeRender` step actually moves); `jumpTo` rewrites `position`/`target` in place and resyncs the control's `_yaw`/`_pitch` so W and drags carry on from the new view, and `dispose` calls the returned detach, which removes the canvas listeners and the per-frame step.

Things I was not fully sure of: the notes document `_yaw = atan2(dx, dz)` but not `_pitch`, so I assumed the matching elevation convention `atan2(dy, hypot(dx, dz))`, clamped to the control's own ±(PI/2−0.01) range; I assumed `SceneContext.camera` is a plain settable field (its declaration isn't in the provided d.ts); and a jump made while a drag is still gliding can't cancel the control's hidden turn velocity (it isn't exposed), so a small amount of glide may linger for a few frames after the jump.
